typedef unsigned char u_char;
typedef unsigned int u_int;

struct nglMaterial {};
struct nglStageStruct
{
  u_char FSAA;
  u_char DMASend;
  u_char Clip;
  u_char BatchDMA;
  u_char Skin;
  u_char XForm;
  u_char Backface;
  u_char Light;
  u_char Kick;
  u_char PlaneClip;
  u_char CommandList;
  u_char DiffusePass;
  u_char DetailPass;
  u_char EnvironmentPass;
  u_char LightPass;
  u_char ProjectedTexturePass;
  u_char FogPass;
};

extern nglStageStruct nglStage;
extern char nglWaveDarkAddr[];
extern char nglBaseAddr[];
extern float DarkAlphaScale;
extern float DarkAlphaOffset;

__asm__(".equ nglStage, 0x004AC9C0");
__asm__(".equ _$nglWaveDarkAddr, 0x003E3220");
__asm__(".equ _$nglBaseAddr, 0x003E16A8");
__asm__(".equ DarkAlphaScale, 0x0041E67C");
__asm__(".equ DarkAlphaOffset, 0x0041E680");

extern char nglWaveDarkAddr[] asm("_$nglWaveDarkAddr");
extern char nglBaseAddr[] asm("_$nglBaseAddr");

#define STAGE_ENABLE( x ) ( nglStage.x )
#define SCE_VIF1_S_32 0x00
#define SCE_VIF1_V2_32 0x04
#define SCE_VIF1_USN ( 1 << 14 )
#define SCE_VIF1_SET_UNPACK(addr, num, vnvl, flg) ((u_int)(0x60 | ((flg) << 7) | (vnvl)) << 24 | ((num) & 0xff) << 16 | ((addr) & 0x3ff))
#define NGL_PROG_ADDR( x, base ) ( ( (u_int)x - (u_int)base ) / 8 )

inline void nglVif1AddCommandListProgram( u_int*& Packet, u_int& DataPtr, char* Addr )
{
  Packet[0] = SCE_VIF1_SET_UNPACK( DataPtr++, 1, SCE_VIF1_S_32, 0 );
  Packet[1] = NGL_PROG_ADDR( Addr, nglBaseAddr );
  Packet += 2;
}

inline void nglVif1AddCommandListData( u_int*& Packet, u_int& DataPtr, int Mode, int QWC, void* Data, int DataSize )
{
  u_int* DataWords = (u_int*)Data;
  *(Packet++) = SCE_VIF1_SET_UNPACK( DataPtr, QWC, Mode, 0 ) | SCE_VIF1_USN;
  do {
    *(Packet++) = *(DataWords++);
    DataSize -= 4;
  } while ( DataSize );
  DataPtr += QWC;
}

void nglVif1AddWaveDark(u_int*& _Packet, u_int& _CmdListDataPtr, nglMaterial* Material, u_int MaterialFlags, bool standalone )
{
	u_int* Packet = _Packet;
	u_int CmdListDataPtr = _CmdListDataPtr;

	if ( !STAGE_ENABLE( DetailPass ) )
		return;

	nglVif1AddCommandListProgram( Packet, CmdListDataPtr, nglWaveDarkAddr );
	float ScaleOffset[] = {DarkAlphaScale, DarkAlphaOffset};
    nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V2_32, 1, (void *) ScaleOffset, sizeof(ScaleOffset) );

	_Packet = Packet;
	_CmdListDataPtr = CmdListDataPtr;

}
